          "text": "この場合において、第2条中「一般席、車いす使用者席、親子席及び報道関係者席に分ける」とあるのは「一般席及び報道関係者席に分ける」と、第3条第1項中「到着順に」とあるのは「委員長が定める方法により」と、第4条中「36名、車いす使用者席の傍聴人の定員は3名、親子席の傍聴人の定員は1組とする」とあるのは「7名とする」と、第3条第2項、第7条第4号、第8条及び前条中「議長」とあるのは「委員長」と、第5条並びに第7条第1号及び第8号中「議場」とあるのは「委員会室」と読み替えるものとする。",
